import { useSyncExternalStore } from 'react';
import { ttsLocaleOf, type LanguageCode } from '@lexpad/core';
import { platform } from './platform/index.js';

/**
 * Whether a speaker button for this language should exist at all. True
 * while the device is still listing its voices, false once it has listed
 * them and this language is not among them.
 */
export function useCanSpeak(lang: LanguageCode): boolean {
  return useSyncExternalStore(
    (listener) => platform.tts.onVoicesChange(listener),
    () => platform.tts.canSpeak(ttsLocaleOf(lang)),
    () => true,
  );
}
